    static bool UserId(string id){return Regex.IsMatch(id??"","^user_[a-f0-9]{32}$");}
    static string StableId(string prefix,string reference){using(var h=SHA256.Create())return prefix+BitConverter.ToString(h.ComputeHash(System.Text.Encoding.UTF8.GetBytes(reference))).Replace("-","").ToLowerInvariant().Substring(0,24);}
