    UserModel GetUserModel(string id,bool allowIncomplete=false){if(!UserId(id))throw new Exception("INVALID_MODEL_ID");UserModel m;if(userModels.TryGetValue(id,out m)){RequireCompleteImport(m,allowIncomplete);return m;}string dir=Path.Combine(UserFolder,id.Substring(5)),file=Path.Combine(dir,"model.json");OwnedPath(file,"user_assemblies");if(!File.Exists(file))throw new Exception("MODEL_NOT_REGISTERED");m=Json.Deserialize<UserModel>(File.ReadAllText(file));if(m.Id!=id||m.Directory!=dir||!m.Files.Contains(m.Path))throw new Exception("MODEL_MANIFEST_INVALID");foreach(string p in m.Files){OwnedPath(p,"user_assemblies");if(!p.StartsWith(Path.Combine(dir,"files")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("MODEL_MANIFEST_INVALID");}SaveUserModel(m);RequireCompleteImport(m,allowIncomplete);return m;}
