    string[] DiskDependencies(string path,bool recurse){var raw=Sw.GetDocumentDependencies2(path,recurse,true,false) as Array;if(raw==null)return new string[0];var v=raw.Cast<object>().Select(Convert.ToString).ToArray();if(v.Length%2!=0)throw new Exception("DEPENDENCY_LIST_INVALID");return Enumerable.Range(0,v.Length/2).Select(i=>Path.GetFullPath(v[2*i+1])).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
