        Progress(activeJobId,"copy_files",0,inputs.Length,null);for(int i=0;i<inputs.Length;i++){File.Copy(inputs[i],m.Files[i],false);File.SetAttributes(m.Files[i],FileAttributes.Normal);Progress(activeJobId,"copy_files",i+1,inputs.Length,null);}
