        AtomicJson(Path.Combine(dir,"import-evidence.json"),new{source_path=source,source_hashes=m.SourceHashes,copy_paths=m.Files,copy_method="disk_copy_then_ReplaceReferencedDocument_before_open",source_documents_opened_by_importer=false});
        if(preserveNames)PrepareGearCopyMetadata(m);object rebuildPreparation=null;Progress(activeJobId,"open_registered_copy",0,0,null);using(var scope=new Scope(this,m.Path,null)){if(!string.IsNullOrEmpty(configuration)&&scope.Doc.ConfigurationManager.ActiveConfiguration.Name!=configuration&&!scope.Doc.ShowConfiguration2(configuration))throw new Exception("CONFIGURATION_NOT_FOUND");m.Configuration=scope.Doc.ConfigurationManager.ActiveConfiguration.Name;Fingerprint(scope.Doc,scope.DocumentPath);InspectUserCore(m,scope.Doc);if(preserveNames){bool rebuiltParts;rebuildPreparation=PrepareImportedRebuild(m,scope.Doc,out rebuiltParts);if(rebuiltParts)SaveOwnedDocuments(m);}Save(scope.Doc,m.Path);}
