    }}
    void VerifyUserSources(UserModel m){foreach(var p in m.SourceHashes)if(!File.Exists(p.Key)||FileHash(p.Key)!=p.Value)throw new Exception("SOURCE_FILE_CHANGED "+p.Key);}
    static IComponent2[] UserComponents(IModelDoc2 d){return ((object[])((IAssemblyDoc)d).GetComponents(false)).Cast<IComponent2>().OrderBy(c=>c.Name2,StringComparer.Ordinal).ToArray();}
    object[] InspectUserCore(UserModel m,IModelDoc2 doc){
        var result=new List<object>();foreach(var c in UserComponents(doc)){bool suppressed=c.IsSuppressed();string path=c.GetPathName();if(c.IsVirtual)throw new CadFault("VIRTUAL_COMPONENT_UNSUPPORTED","原生确认存在虚拟组件；默认路径不支持内嵌零件，请使用显式受限副本外部化。",new{model_id=m.Id,instance=c.Name2,native_is_virtual=true,required_option="materialize_virtual_components"});if(!suppressed&&(!File.Exists(path)||!path.StartsWith(Path.Combine(m.Directory,"files")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)))throw new Exception("COPY_REFERENCE_NOT_ISOLATED "+c.Name2);
            string reference=Convert.ToBase64String((byte[])doc.Extension.GetPersistReference3(c)),id=StableId("component_",reference);m.Components[id]=reference;bool sub=path.EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase);var transform=c.Transform2==null?null:(double[])c.GetTotalTransform(false).ArrayData;
            result.Add(new{component_id=id,instance=c.Name2,path=path,configuration=c.ReferencedConfiguration,suppressed=suppressed,loaded=c.GetModelDoc2()!=null,fixed_component=c.IsFixed(),fixed_state_source="IComponent2.IsFixed",assembly_configuration=doc.ConfigurationManager.ActiveConfiguration.Name,subassembly=sub,solving=c.Solving,speedpak=c.IsSpeedPak,transform=transform});}
        return result.ToArray();
    }
    IComponent2 ResolveUserComponent(UserModel m,IModelDoc2 doc,string id){return ResolveUserComponent(m,doc.Extension,id);}
    IComponent2 ResolveUserComponent(UserModel m,IModelDocExtension extension,string id){string reference;if(!m.Components.TryGetValue(id,out reference))throw new CadFault("COMPONENT_ID_NOT_FOUND","组件标识不存在或不属于当前登记模型；请重新查询当前模型组件。",new{model_id=m.Id,requested_component_id=id,required_tool="inspect_model",required_arguments=new{model_id=m.Id,detail_level="components"},automatic_prefix_or_name_matching=false});int e;var c=extension.GetObjectByPersistReference3(Convert.FromBase64String(reference),out e) as IComponent2;if(c==null||e!=0)throw new Exception("COMPONENT_REFERENCE_STALE");return c;}
    public object InspectUserModel(string id,string detailLevel="full") {
        if(detailLevel=="components")return InspectUserComponents(id);
        if(detailLevel!="full")throw new Exception("INVALID_INSPECTION_DETAIL_LEVEL");
        var total=System.Diagnostics.Stopwatch.StartNew();var m=GetUserModel(id);
        using(var scope=new Scope(this,m.Path,null)) {
            double scopeMs=total.Elapsed.TotalMilliseconds;var timer=System.Diagnostics.Stopwatch.StartNew();
            var batch=new NativeCommandBatch(()=>Sw.CommandInProgress,v=>Sw.CommandInProgress=v);
            object[] components=null,mates=null;object structure=null;string configuration=null;bool unchanged=false;
            double fingerprintMs=0,componentsMs=0,matesMs=0,structureMs=0,metadataMs=0;
            try {
                timer.Restart();Fingerprint(scope.Doc,scope.DocumentPath);fingerprintMs=timer.Elapsed.TotalMilliseconds;
                Log("INSPECTION_STAGE components");timer.Restart();components=InspectUserCore(m,scope.Doc);componentsMs=timer.Elapsed.TotalMilliseconds;
                Log("INSPECTION_STAGE mates");timer.Restart();mates=UserMates(scope.Doc,m);matesMs=timer.Elapsed.TotalMilliseconds;
                Log("INSPECTION_STAGE structure");timer.Restart();structure=AssemblyStructureObservation(scope.Doc);structureMs=timer.Elapsed.TotalMilliseconds;
                timer.Restart();SaveUserModel(m);configuration=scope.Doc.ConfigurationManager.ActiveConfiguration.Name;unchanged=UserSourcesUnchanged(m);metadataMs=timer.Elapsed.TotalMilliseconds;
            }finally{batch.Dispose();}
            Log("INSPECTION_DONE mates="+mates.Length+" elapsed_ms="+total.Elapsed.TotalMilliseconds.ToString("F3",CultureInfo.InvariantCulture));
            return new{model_id=id,mate_health=MateHealthSummary(mates,"current_native_observation_no_implicit_rebuild"),configuration=configuration,
                components=components,mates=mates,structural_relations=structure,
                inspection_timing=new{scope_enter_ms=scopeMs,fingerprint_ms=fingerprintMs,components_ms=componentsMs,mates_ms=matesMs,
                    structure_ms=structureMs,metadata_ms=metadataMs,elapsed_before_scope_exit_ms=total.Elapsed.TotalMilliseconds,
                    native_batch=batch.Export(),implicit_rebuild=false,scope="native_full_inspection_before_scope_disposal_and_transport_serialization"},
                reference_guidance=new{source="supported_returned_faces_registered_after_owner_and_native_reference_validation",model_id=id,required_mate_query=new{tool="list_mate_references",model_id=id,component_id="select_component_id_from_entities",kind="select_kind_from_geometry",limit=20},required_drive_query=new{tool="list_drive_candidates",model_id=id,group_faces=false,limit=20},registration_scope="supported_returned_top_level_face_references_only",ordinary_revision_change_clears_registration=false,checkpoint_restore_may_remove_later_registrations=true,automatic_rebinding=false},units=new{reference_points="m",areas="m2",mate_distance_input="mm",linear_drive_input="mm/s",rotary_drive_input="rpm",curve_values="declared_per_quantity"},degrees_of_freedom=new{status="unknown",reason="not inferred from mate count; native solver diagnostics and drive validation required"},source_files_unchanged=unchanged};
        }
    }
    bool UserSourcesUnchanged(UserModel m){return m.SourceHashes.All(p=>File.Exists(p.Key)&&FileHash(p.Key)==p.Value);}
    static string StudyTypeName(int type){return type==1?"animation":type==2?"basic_motion":type==4?"motion_analysis":"unsupported_native_type";}
    static string HistoryErrorCode(Exception e){var fault=e as CadFault;return fault!=null?fault.Code:e is COMException?"COM_CALL_FAILED":e is IOException?"FILE_ACCESS_FAILED":e is InvalidCastException?"API_TYPE_MISMATCH":StudyHistory.ErrorCode(e.Message)??"CAD_OPERATION_FAILED";}
    public object UserStudies(string id,bool inspectNativeDrives=false) {
        var m=GetUserModel(id);var observation=new StudyHistory.Observation();
        ObserveHistory(m,observation,"before_load_motion");LoadUserMotion();ObserveHistory(m,observation,"after_load_motion");
        using(var scope=new Scope(this,m.Path,null)) {
            ObserveHistory(m,observation,"after_scope_open");Fingerprint(scope.Doc,scope.DocumentPath);ObserveHistory(m,observation,"after_fingerprint");
            var manager=(IMotionStudyManager)scope.Doc.Extension.GetMotionStudyManager();var rows=new List<Dictionary<string,object>>();
            foreach(string name in Names(manager)) {
                var study=(IMotionStudy)manager.GetMotionStudy(name);bool active=study.IsActive;string raw;
                var features=MotionFeatures(study,out raw);var settings=HistorySettings(study);UserDrive drive;m.Drives.TryGetValue(name,out drive);
                rows.Add(new Dictionary<string,object>{{"name",name},{"type",study.StudyType},{"study_type_name",StudyTypeName(study.StudyType)},{"time_s",study.GetTime()},{"duration_s",settings["duration_s"]},{"output_fps",settings["fps"]},{"active",study.IsActive},{"motion_features",features},{"feature_enumeration_status",MotionFeatureEvidence.Status(raw,active)},{"native_feature_enumeration_status",raw},{"enumeration_study_active",active},{"feature_presence",MotionFeatureEvidence.Presence(raw,features.Length)},{"empty_feature_list_means_no_drive",false},{"enumeration_activation_requirement","not_proven"},{"feature_information_source","native_api"},{"drive_inventory_complete",false},{"drive_status",drive==null?"native_drive_inventory_not_proven":"registered_constant_speed_drive"},{"drive_information_source",drive==null?"unproven_native_inventory":"project_registration"},{"registered_drive",drive},{"registered_drive_native_reference_observation",inspectNativeDrives?RegisteredDriveReferenceEvidence(scope.Doc,drive):null},{"enumeration_guidance","activation_is_not_proven_to_fix_null_inventory; explicit_inspect_native_drives_adds_separate_unassigned_observations"},{"registered_drive_native_verification","not_verified_by_feature_enumeration"},{"drive_compatibility_status","not_checked"}});
            }
            var nativeObservations=inspectNativeDrives?UnassignedMotorFeatureObservations(scope.Doc):null;ObserveHistory(m,observation,"after_optional_native_inventory");
            ObserveHistory(m,observation,"after_feature_enumeration");var hashes=HistoryCurrentHashes(m);
            foreach(var row in rows) {
                var settings=new Dictionary<string,object>{{"type",row["type"]},{"fps",row["output_fps"]},{"duration_s",row["duration_s"]}};
                var history=StudyHistory.Latest(Root,id,(string)row["name"],m.Revision,m.Configuration,hashes,observation,settings);
                foreach(string key in new[]{"last_run","run_history_status","history_warning"})row[key]=history[key];
            }
            return new{model_id=id,studies=rows.ToArray(),unassigned_native_motor_observations=nativeObservations,input_observation=observation.Export()};
        }
    }
    object[] MotionFeatures(IMotionStudy study,out string status){try{var raw=study.GetMotionFeatures();var features=raw as Array;if(features==null){status=raw==null?"native_null":"unsupported_variant";return new object[0];}status="enumerated";return features.Cast<object>().Select(v=>{var f=v as IFeature;if(f==null)throw new InvalidCastException("MOTION_FEATURE_VARIANT");var motor=f.GetDefinition() as ISimulationMotorFeatureData;return (object)new{name=f.Name,type=f.GetTypeName2(),motor_type=motor==null?(int?)null:motor.MotorType,motion_type=motor==null?(int?)null:motor.MotionType,magnitude_raw=motor==null?(double?)null:motor.Magnitude};}).ToArray();}catch(COMException){status="com_enumeration_failed";return new object[0];}catch(InvalidCastException){status="unsupported_variant";return new object[0];}}
