    object UserPreflight(UserModel m,IModelDoc2 doc,string studyName,bool resolve,StudyHistory.Observation observation=null){
        observation=observation??new StudyHistory.Observation();ObserveHistory(m,observation,"before_preflight");
        Fingerprint(doc,m.Path);ObserveHistory(m,observation,"after_fingerprint");if(resolve)((IAssemblyDoc)doc).ResolveAllLightWeightComponents(true);ObserveHistory(m,observation,"after_resolve");var c=UserComponents(doc);var blockers=new List<string>();var warnings=new List<string>();
        if(c.Length>500)blockers.Add("COMPONENT_BUDGET_EXCEEDED");if(c.Length==0)blockers.Add("EMPTY_ASSEMBLY");var active=c.Where(v=>!v.IsSuppressed()).ToArray();if(active.All(v=>v.IsFixed()))blockers.Add("ALL_COMPONENTS_FIXED");
        foreach(var v in active){if(v.IsSpeedPak)blockers.Add("SPEEDPAK "+v.Name2);if(v.GetModelDoc2()==null)blockers.Add("UNRESOLVED_COMPONENT "+v.Name2);if(v.GetPathName().EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase)&&v.Solving==1)blockers.Add("FLEXIBLE_SUBASSEMBLY_NOT_VALIDATED "+v.Name2);}
        bool rebuild=doc.EditRebuild3();ObserveHistory(m,observation,"after_rebuild");if(!rebuild)blockers.Add("REBUILD_FAILED");var featureDiagnostics=NativeFeatureDiagnostics(doc);if(featureDiagnostics.Length>0)blockers.Add("FEATURE_ERROR_COUNT: "+featureDiagnostics.Length);foreach(var item in featureDiagnostics){var d=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(item));if((bool)d["warning"])warnings.Add("FEATURE_WARNING "+d["name"]);}

        var nativeHealth=NativeMateHealth(doc);foreach(var row in nativeHealth){var d=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(row));if(Convert.ToInt32(d["error"])!=0)blockers.Add("MATE_ERROR "+d["name"]);}
        var mgr=(IMotionStudyManager)doc.Extension.GetMotionStudyManager();if(!string.IsNullOrEmpty(studyName)){var study=(IMotionStudy)mgr.GetMotionStudy(studyName);if(study==null)blockers.Add("STUDY_NOT_FOUND");else if(study.StudyType!=4)blockers.Add("MOTION_ANALYSIS_REQUIRED_EXPLICIT_CONVERSION");}
        warnings.Add("DOF_NOT_PROVEN_FROM_MATE_COUNT");warnings.Add("DRIVE_COMPATIBILITY_NOT_CHECKED");Dictionary<string,object> history=null;
        if(!string.IsNullOrEmpty(studyName)){var hashes=HistoryCurrentHashes(m);var selected=(IMotionStudy)mgr.GetMotionStudy(studyName);history=StudyHistory.Latest(Root,m.Id,studyName,m.Revision,m.Configuration,hashes,observation,selected==null?null:HistorySettings(selected));if(history["history_warning"]!=null)warnings.Add((string)history["history_warning"]);}
        if(c.Any(v=>v.IsSuppressed()))warnings.Add("SUPPRESSED_INSTANCES_EXCLUDED_FROM_ACTIVE_MOTION_SCOPE");InspectUserCore(m,doc);SaveUserModel(m);
        return new{model_id=m.Id,basic_ready=blockers.Count==0,basic_input_ready=blockers.Count==0,ready=blockers.Count==0,ready_is_legacy_basic_input_alias=true,readiness_status=blockers.Count==0?"basic_inputs_ready_solver_not_tested":"basic_inputs_blocked",solver_compatibility_status="not_checked",mate_preparation_guidance=new{initial_time_checked=false,reason="basic_motion_preflight_does_not_run_mate_initial_time_gate",required_tool="list_motion_studies",nonzero_study_next_tool="reset_study_time",automatic_reset=false,new_preview_after_reset_required=true},mate_health=new{observation_scope="native_feature_errors_after_explicit_preflight_rebuild",mate_count=nativeHealth.Length,error_count=nativeHealth.Count(v=>Convert.ToInt32(Json.Deserialize<Dictionary<string,object>>(Json.Serialize(v))["error"])!=0),geometry_inspected=false,unavailable_reference_summary=(object)null,unavailable_reference_summary_status="not_inspected_not_zero",reference_diagnostics_query=new{tool="inspect_model",model_id=m.Id,detail_level="full"},claim="feature_health_not_geometry_or_DOF"},feature_diagnostics=featureDiagnostics,feature_error_summary=FeatureErrorGroups(featureDiagnostics),feature_error_origin="not_proven_source_or_import_requires_separate_baseline",ready_scope="basic_model_preflight_only_not_solver_compatibility",solver_compatibility_verified=false,input_observation=observation.Export(),drive_compatibility_status="not_checked",compatibility_probe=new{attempted=false,reason="not_requested_set_compatibility_probe_true"},last_run=history==null?null:history["last_run"],run_history_status=history==null?"study_not_selected":history["run_history_status"],blockers=blockers.Distinct().ToArray(),warnings=warnings.Distinct().ToArray(),components=c.Length,active_components=active.Length,omitted_suppressed_instances=c.Where(v=>v.IsSuppressed()).Select(v=>v.Name2).ToArray(),degrees_of_freedom_status="unknown",native_rebuild_succeeded=rebuild,configuration=doc.ConfigurationManager.ActiveConfigu