    void ValidateUserStoredRun(Run r){
        var m=GetUserModel(r.Assembly);var reasons=new List<string>();
        var result=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(r.Directory,"solve.json")));
