        bool configurationMatch=hasConfiguration&&(string)configuration==m.Configuration;if(hasConfiguration&&!configurationMatch)reasons.Add("REGISTERED_CONFIGURATION_CHANGED");
        if(reasons.Count>0)throw new CadFault("MODEL_REVISION_CHANGED","历史结果输入已改变，请重新求解；显式历史摘要与曲线仍可离线读取。",new{run_id=r.Id,recorded_revision=r.EditVersion,current_revision=m.Revision,revision_match=m.Revision==r.EditVersion,file_hashes_match=r.FileHashes!=null&&changed.Length==0,changed_input_paths=changed.Take(8).ToArray(),changed_input_count=changed.Length,diagnostic_path_limit=8,recorded_configuration=configuration,registered_configuration=m.Configuration,registered_configuration_match=hasConfiguration?(bool?)configurationMatch:null,live_configuration_status="not_checked_without_COM",recorded_study=r.Study,live_study_status="not_checked_without_COM",input_identity_status="changed",source_files_unchanged_scope="original_import_sources_not_working_copy_inputs",byte_change_cause="not_proven_checkpoint_save_may_rewrite_owned_copy",mechanical_equivalence_status="not_proven_by_component_counts_or_transforms",reasons=reasons,offline_tools=new[]{"get_run_artifacts","read_run_poses","get_motion_summary","export_motion_curve"},history_option=new{allow_unverified_history=true},replay_history_option=new{saved_image_only=true,scope="previously_recorded_verified_images_only_no_new_CAD_capture"},snapshot_replay_option=new{tool="replay_motion_frame",run_id=r.Id,use_input_snapshot=true,wait_for_completion=false,bound_snapshot_available=result.ContainsKey("replay_input_snapshot"),scope="independent_frozen_input_not_current_model",legacy_snapshot_guessing=false},historical_image_missing_next_step="use_explicit_input_snapshot_replay_if_bound_snapshot_available_otherwise_create_a_new_run",current_replay_allowed=false});
        if((string)result["result_validity"]!="verified")throw new CadFault("RESULTS_UNVERIFIED","结果未通过完整验证；可使用离线接口审查，不能据此判为运动通过。",new{run_id=r.Id,offline_tools=new[]{"get_run_artifacts","read_run_poses"},result_validity=result["result_validity"]});
        if(FileHash(Path.Combine(r.Directory,"component-poses.csv"))!=(string)result["poses_sha256"])throw new Exception("RESULT_ARTIFACT_CHANGED");
    }
