    public object CreateUserCheckpoint(string id){using(var saveObservationScope=BeginSaveObservationOperation("create_model_checkpoint")){WriteStage("checkpoint_snapshot");LoadUserMotion();var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null)){Fingerprint(s.Doc,s.DocumentPath);ObserveOwnedSave(m,"before_checkpoint_save");SaveOwnedDocuments(m);ObserveOwnedSave(m,"after_checkpoint_save");var states=StudyStates(s.Doc);string cp=Guid.NewGuid().ToString("N"),dir=Path.Combine(m.Directory,"checkpoints",cp);Directory.CreateDirectory(dir);var files=new Dictionary<string,string>();foreach(string path in m.Files){string copy=Path.Combine(dir,Path.GetFileName(path));File.Copy(path,copy,false);files[path]=FileHash(copy);}var descriptor=new{checkpoint_id=cp,model_id=id,created_at_utc=DateTime.UtcNow.ToString("o"),snapshot_source="registered_copy_before_operation",files=files,configuration=s.Doc.ConfigurationManager.ActiveConfiguration.Name,poses=Transforms(s.Doc),studies=states,model=m};AtomicJson(Path.Combine(dir,"checkpoint.json"),descriptor);return new{model_id=id,checkpoint_id=cp,file_count=files.Count,checkpoint_path=Path.Combine(dir,"checkpoint.json"),plan_guidance=new{save_may_invalidate_existing_plans=true,required_next_tool="preview_mate",automatic_revalidation=false},studies=states,save_observation=SaveObservation(m)};}}}
    void CloseUserDocuments(string[] paths){var documents=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Select(doc=>new{path=doc.GetPathName(),title=doc.GetTitle(),type=doc.GetType()}).Where(doc=>paths.Contains(doc.path,StringComparer.OrdinalIgnoreCase)).OrderByDescending(doc=>doc.type).ToArray();foreach(var item in documents)if((Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Any(doc=>doc.GetPathName().Equals(item.path,StringComparison.OrdinalIgnoreCase)))Sw.CloseDoc(item.title);}
