            if(s.Doc.ConfigurationManager.ActiveConfiguration.Name!=(string)d["configuration"])throw new Exception("CHECKPOINT_CONFIGURATION_MISMATCH");var actual=Transforms(s.Doc);var expected=Json.Deserialize<Dictionary<string,double[]>>(Json.Serialize(d["poses"]));var difference=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(PoseDifference(expected,actual)));double delta=Convert.ToDouble(difference["maximum_transform_delta"]);if(delta>1e-7||files.Any(f=>FileHash(f.Key)!=(string)f.Value))throw new CadFault("CHECKPOINT_RESTORE_UNVERIFIED","检查点姿态或文件核验失败。",difference);Fingerprint(s.Doc,s.DocumentPath);bool sourcesUnchanged=UserSourcesUnchanged(restored);LastOperationRestoration="restored";return new{model_id=id,checkpoint_id=cp,restoration_status="restored",maximum_transform_delta=delta,pose_difference=difference,studies=StudyStates(s.Doc),results_invalidated=true,invalidates_previous_baselines=true,baseline_invalidation_scope="all_existing_runs_for_this_registered_model_revision_and_file_hashes_rechecked_no_automatic_rebinding",model_revision=restored.Revision,revision_before=m.Revision,revision_change_reason="checkpoint_restore",revision_bumped_by_restore=true,source_files_unchanged=sourcesUnchanged,simulation_input="checkpoint_imported_copy",restore_changes=restoreChanges};}
